const fs = require("fs");
const path = require("path");

const handlerPath = path.join(__dirname, "..", ".open-next", "server-functions", "default", "handler.mjs");

if (!fs.existsSync(handlerPath)) {
  console.log("handler.mjs not found, skipping patch");
  process.exit(0);
}

let content = fs.readFileSync(handlerPath, "utf-8");
const originalSize = Buffer.byteLength(content);

const patches = [
  {
    name: "Remove @vercel/og edge import redirect",
    from: 'id==="next/dist/compiled/@vercel/og/index.node.js"?raw=await import("next/dist/compiled/@vercel/og/index.edge.js"):raw=await import(id)',
    to: 'id==="next/dist/compiled/@vercel/og/index.node.js"?raw={}:raw=await import(id)',
  },
];

let patched = 0;
for (const patch of patches) {
  if (content.includes(patch.from)) {
    content = content.replaceAll(patch.from, patch.to);
    patched++;
    console.log(`Applied: ${patch.name}`);
  } else {
    console.log(`Skipped (not found): ${patch.name}`);
  }
}

if (patched > 0) {
  fs.writeFileSync(handlerPath, content);
  const newSize = Buffer.byteLength(content);
  console.log(`Size: ${(originalSize / 1024).toFixed(1)} KiB → ${(newSize / 1024).toFixed(1)} KiB (${patched} patches)`);
}

