export default withNextIntl(nextConfig);
```

Deployment & PM2 Configuration:

Here is our CI/CD pipeline and PM2 configuration for additional context on our production environment.

```name: CI/CD pipeline
on:
  push:
    branches: [ master ]
jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
      - name: Setup Node.js environment
        uses: actions/setup-node@v3
        with:
          node-version: '22'
      - name: Cache dependencies
        uses: actions/cache@v3
        with:
          path: ~/.npm
          key: ${{ runner.os }}-node-${{ hashFiles('**/package-lock.json') }}
      - name: Install Dependencies
        run: npm ci --legacy-peer-deps
      - name: Build
        run: npm run build
        env:
          CI: false
      - name: Deploy to Server
        run: |
          rsync -avz --delete \
            --exclude=".git/" \
            --exclude="public/sitemap/" \
            --exclude="node_modules/" \
            ./ ${{ secrets.REMOTE_USER }}@${{ secrets.REMOTE_HOST }}:/path/to/app/
      - name: Install prod dependencies on server
        run: |
          ssh ${{ secrets.REMOTE_USER }}@${{ secrets.REMOTE_HOST }} \
            "cd /path/to/app && npm ci --omit=dev --legacy-peer-deps"
      - name: Reload PM2 App
        run: |
          ssh ${{ secrets.REMOTE_USER }}@${{ secrets.REMOTE_HOST }} \
          "cd /path/to/app && /home/user/.nvm/versions/node/v20.13.0/bin/pm2 startOrReload ecosystem.config.js --env production"
          ```

ecosystem.config.js : 

```module.exports = {
  apps : [{
    name   : "my-next-app",
    script : "./node_modules/.bin/next",
    args   : "start",
    interpreter: "/home/user/.nvm/versions/node/v20.13.0/bin/node",
    env_production: {
       NODE_ENV: "production"
    },
    node_args: "--unhandled-rejections=strict",
    log_date_format: "YYYY-MM-DD HH:mm:ss Z",
    max_memory_restart: "2G"
  }]
}
```

Partial package.json Dependencies:

We are using Next.js ^15.4.3 and React 19.1.0.

```{
  "name": "my-next-app",
  "version": "2.0.0",
  "dependencies": {
    "@next/third-parties": "15.3.2",
