    "next-intl": "^4.0.0",
    "react": "19.1.0",
    "react-dom": "19.1.0",
    "sharp": "^0.34.2",
    "undici": "^6.21.3",
    "...": "..."
  },
  "devDependencies": {
    "eslint-config-next": "15.3.2",
    "typescript": "^5",
    "webpack": "^5.89.0",
    "...": "..."
  }
