The key fix here is indeed:

```ts
export const config = {
  api: {
    bodyParser: false,
  },
}
```

Otherwise Next.js consumes the request before Multer can properly handle the multipart stream.

Once that part is fixed, I’d also recommend adding an **inspect-before-store** step instead of sending the file straight to disk or S3.

That’s what I built [[Pompelmi](https://github.com/pompelmi/pompelmi)](https://github.com/pompelmi/pompelmi) for.

Example with in-memory Multer storage:

```ts
import nextConnect from 'next-connect'
import multer from 'multer'
import { scanBytes, STRICT_PUBLIC_UPLOAD } from 'pompelmi'

export const config = {
  api: {
    bodyParser: false,
  },
}

const upload = multer({ storage: multer.memoryStorage() })
const handler = nextConnect()

handler.use(upload.single('file'))

handler.post(async (req: any, res: any) => {
  if (!req.file) {
    return res.status(400).json({ error: 'Missing file' })
  }

  const report = await scanBytes(req.file.buffer, {
    filename: req.file.originalname,
    mimeType: req.file.mimetype,
    policy: STRICT_PUBLIC_UPLOAD,
    failClosed: true,
  })

  if (report.verdict !== 'clean') {
    return res.status(400).json({ error: `Rejected: ${report.verdict}` })
  }

  // persist/promote only after inspection
  return res.status(200).json({ ok: true, verdict: report.verdict })
})

export default handler
```

So I’d treat `bodyParser: false` as the parsing fix, and then add a separate security gate before persistence.

