"use client"
import { useState } from "react";
import { type PutBlobResult, BlobError } from "@vercel/blob";
import { upload as vercelUpload } from "@vercel/blob/client";

//Utils
import { uniqueFilename } from "./client";

//Types
type UseUploadOptions = {
    onError?: (error: { message: string }) => void;
    ext?: string;
};
export type UseUploadResponse = {
    blob: PutBlobResult | null;
}
type UploadConfig = {
    url?: string | null;
}

export const useUpload = (options?: UseUploadOptions) => {
    const [isUploading, setIsUploading] = useState(false);
    const [isSuccess, setIsSuccess] = useState(false);
    const [error, setError] = useState<string>("");

    const upload = async (file: File | Blob | undefined | null, config?: UploadConfig): Promise<UseUploadResponse> => {
        if (!file) return {
            blob: null
        }
        try {
            setIsUploading(true);
            setIsSuccess(false);
            if (config?.url) {
                fetch("/api/blob", {
                    method: "DELETE",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ url: config.url }),
                    keepalive: true
                }).catch(() => { });
            }
            const folder = process.env.NEXT_PUBLIC_BLOB_FOLDER_NAME || "common";
            const newBlob = await vercelUpload(`${folder}/${uniqueFilename((file as File).name, options?.ext)}`, file, {
                access: "public",
                handleUploadUrl: "/api/blob"
            })
            return {
                blob: newBlob
            };
        } catch (error) {
            if (error instanceof BlobError) {
                const message = error?.message || "Something went wrong on file uploading"
                options?.onError?.({ message });
                setError(message);
            } else {
                const message = "Something went wrong on file uploading"
                options?.onError?.({ message });
                setError(message);
            }
            return {
                blob: null
            }
        } finally {
            setIsUploading(false);
            setIsSuccess(true);
        }
    };

    return { isUploading, upload, isSuccess, error };
};
```


